CREATE TABLE evidence_versions (version_id TEXT PRIMARY KEY, project_id TEXT NOT NULL, parent_version_id TEXT NOT NULL, stage TEXT NOT NULL CHECK(stage IN ('INPUT','SCREENING','FULLTEXT','INCLUDED','EXTRACTION','VERIFIED','ROB','READY')), source_job_id TEXT UNIQUE, actor_id TEXT NOT NULL REFERENCES app_users(id), created_at TEXT NOT NULL, FOREIGN KEY(version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(parent_version_id,project_id) REFERENCES project_versions(id,project_id), FOREIGN KEY(source_job_id,project_id,parent_version_id) REFERENCES jobs(id,project_id,version_id));
